u_1 \\
u_2\\
\end{bmatrix} \\
\begin{bmatrix}
F +\frac{1}{4}n\ell A \\
\frac{1}{2}n\ell A \\
\end{bmatrix} & =
\frac{2EA}{\ell}\begin{bmatrix}
1 & -1\\
-1 & 2 \\
\end{bmatrix} \begin{bmatrix}
u_1 \\
